const smooth=t=>{t=clamp(t,0,1);return t*t*(3-2*t);};
const rad=Math.PI/180;
export function solarVector(latitude,day,hour){let g=2*Math.PI/365*(day-1+(hour-12)/24),decl=.006918-.399912*Math.cos(g)+.070257*Math.sin(g)-.006758*Math.cos(2*g)+.000907*Math.sin(2*g)-.002697*Math.cos(3*g)+.00148*Math.sin(3*g),lat=latitude*rad,ha=(hour-12)*15*rad;return[-Math.cos(decl)*Math.sin(ha),Math.sin(lat)*Math.cos(decl)*Math.cos(ha)-Math.cos(lat)*Math.sin(decl),Math.sin(lat)*Math.sin(decl)+Math.cos(lat)*Math.cos(decl)*Math.cos(ha)];}
