export function vegetationAt(doc,field,x,y){let g=doc.ecology?.grid;if(!g)return null;let i=clamp(Math.floor(x/.1),0,199),j=clamp(Math.floor(y/.1),0,159),k=j*200+i;return{exposure:g.exposure[k]/100,moisture:g.moisture[k]/100,forestLine:g.forestLine[k],meadowLine:g.meadowLine[k],tree:g.tree[k]/100,shrub:g.shrub[k]/100,grass:g.grass[k]/100,community:g.community[k]};}
