 let originals=doc.features.filter(f=>['forest','grassland','meadow'].includes(f.type)),forests=originals.filter(f=>f.type==='forest'),open=originals.filter(f=>f.type!=='forest'),lakes=doc.features.filter(f=>f.type==='lake'),nx=200,ny=160,N=nx*ny,grid=Object.fromEntries(['exposure','moisture','forestLine','meadowLine','tree','shrub','grass','community'].map(k=>[k,new Array(N)])),owners=new Int16Array(N).fill(-1),masks=originals.map(()=>new Uint8Array(N));
