  if(wet){tree=shrub=grass=0;}
  else if(e.h<=e.forestLine&&e.slope<.8&&(forestSeed||!openSeed&&tree>.42)){type='forest';owner=forestSeed?originals.indexOf(forestSeed):-1;}
  else if(e.h<=e.meadowLine&&e.slope<1.0){type=openSeed?.type||(e.h>e.forestLine-130?'meadow':'grassland');owner=openSeed?originals.indexOf(openSeed):-1;tree*=type==='grassland'?.12:.08;}
