 originals.forEach((f,i)=>emit(masks[i],f,'original-'+i));
 emit(autoForest,{type:'forest',name:'山麓林带'},'forest');emit(autoMeadow,{type:'meadow',name:'高山花甸'},'meadow');emit(autoGrass,{type:'grassland',name:'河谷草坡'},'grass');
